func NewMock() (*PrismaClient, *Mock, func(t *testing.T)) {
	expectations := new([]mock.Expectation)
	pc := newMockClient(expectations)
	m := &Mock{
		Mock: &mock.Mock{
			Expectations: expectations,
		},
	}

	m.User = userMock{
		mock: m,
	}

	m.Account = accountMock{
		mock: m,
	}

	m.Session = sessionMock{
		mock: m,
	}

	m.VerificationToken = verificationTokenMock{
		mock: m,
	}

	m.Project = projectMock{
		mock: m,
	}

	m.ProjectImage = projectImageMock{
		mock: m,
	}

	m.Category = categoryMock{
		mock: m,
	}

	m.Tag = tagMock{
		mock: m,
	}

	m.ProjectCategory = projectCategoryMock{
		mock: m,
	}

	m.ProjectTag = projectTagMock{
		mock: m,
	}

	m.Career = careerMock{
		mock: m,
	}

	m.Education = educationMock{
		mock: m,
	}

	m.Resume = resumeMock{
		mock: m,
	}

	m.Contact = contactMock{
		mock: m,
	}

	m.SiteSetting = siteSettingMock{
		mock: m,
	}

	return pc, m, m.Ensure
}

